'use strict';
const root=document.getElementById('game');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readGame=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},saveGame=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{}};
const newSeed=()=>{try{return crypto.getRandomValues(new Uint32Array(1))[0]}catch{return Date.now()>>>0}};
let selected=[0,1,5],state=null,soft=readGame('tw-game-soft',false)===true,collection=readGame('tw-game-endings',[]),mapSeed=newSeed(),destination=null,previewDestination=null;
if(!Array.isArray(collection))collection=[];collection=[...new Set(collection.filter(id=>Object.hasOwn(survivalEndingBook,id)))];
let resumable=SurvivalEngine.restore(readGame('tw-game-save',null));document.getElementById('soft').checked=soft;
const money=n=>n.toLocaleString('ko-KR')+'원',minutes=n=>Math.floor(n/60)?`${Math.floor(n/60)}시간${n%60?' '+n%60+'분':''}`:`${n}분`;
const speak=s=>escapeHTML(soft?s.replace(/ㅋㅋ시발/g,'ㅋㅋ아이고').replace(/씨바|시발|스바|ㅅㅂ|존나/g,'아이고'):s);
const face=p=>`<span class="avatar" style="background-position:${p.id%4*100/3}% ${Math.floor(p.id/4)*50}%" aria-hidden="true"></span>`;
const persist=()=>saveGame('tw-game-save',state);
function bubbles(p,lines){return `<div class="speaker">${face(p)}<div><strong>${p.name}</strong><div class="burst">${lines.map(l=>`<span>${speak(l)}</span>`).join('')}</div></div></div>`;}
function routesSVG(id){if(!id)return '';const target=Travel.project(survivalCities[id]);return selected.map((pid,i)=>{const from=Travel.project(survivalCities[survivalHomes[pid]]),km=Travel.distance(survivalCities[survivalHomes[pid]],survivalCities[id]),control=[(from[0]+target[0])/2+40,(from[1]+target[1])/2-35];return `<path class="travel-line" d="M${from} Q${control} ${target}" style="--route-color:${['#e5ed95','#b2c8ff','#ffbd96'][i]}"/><circle class="origin" cx="${from[0]}" cy="${from[1]}" r="4"><title>${survivalCast[pid].name} · ${survivalCities[survivalHomes[pid]].name} 출발 · 직선 ${km}km</title></circle>`}).join('');}
function mapSVG(candidates){const labelOffsets={seoul:[14,-12],incheon:[-18,25],daejeon:[-35,21],jecheon:[15,8],gumi:[-25,23],changwon:[-60,20],busan:[14,14]};return `<svg class="korea-map" viewBox="50 0 620 770" aria-label="대한민국 지도, 오늘 후보 5곳. 버튼을 누르거나 목록에서 선택하세요." role="group"><defs><pattern id="map-grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#334d40" stroke-width=".5"/></pattern><linearGradient id="land" x2="1" y2="1"><stop stop-color="#385848"/><stop offset="1" stop-color="#203b33"/></linearGradient></defs><rect x="50" width="620" height="770" fill="url(#map-grid)"/><path class="korea-land" d="${survivalKoreaPath}"/><text x="500" y="330" class="sea-label">동해</text><text x="100" y="465" class="sea-label">서해</text><text x="302" y="665" class="sea-label">남해</text><text x="170" y="735" class="map-small-label">제주</text><text x="587" y="165" class="map-small-label">울릉도</text><g id="travel-routes">${routesSVG(previewDestination||destination)}</g>${candidates.map((r,i)=>{const [x,y]=Travel.project(survivalCities[r.id]),offset=labelOffsets[r.id]||[15,-12];return `<g role="button" tabindex="0" data-pin="${r.id}" class="map-pin ${destination===r.id?'picked':''}" aria-label="${r.name} 모임 장소 선택" aria-pressed="${destination===r.id}" style="--pin-color:${r.color}"><title>${r.name} · ${r.district} · ${r.subtitle}</title><circle class="pin-halo" cx="${x}" cy="${y}" r="22"/><circle class="pin-dot" cx="${x}" cy="${y}" r="9"/><text x="${x+offset[0]}" y="${y+offset[1]}" class="pin-label">${r.name}</text></g>`}).join('')}<g class="map-compass" transform="translate(565 600)"><path d="M0 -22L-6 8L0 4L6 8Z"/><text y="-34" text-anchor="middle">N</text></g></svg>`;}
function destinationPanel(id){const r=Travel.region(id),commute=Travel.commute(selected,id);return `<div class="destination-art" style="--city-color:${r.color}"><span>${r.emoji}</span><small>${r.district}</small></div><div class="destination-heading"><div><p class="eyebrow">${destination===id?'선택한 모임 장소':'오늘의 모임 후보'}</p><h2>${r.name}</h2></div><span class="city-index">${String(survivalRegions.indexOf(r)+1).padStart(2,'0')}</span></div><p class="destination-story">${r.subtitle}</p><div class="venue-stops"><span>${r.hub}</span><i>→</i><span>${r.walk}</span><i>→</i><span>${r.district}</span></div><div class="commute-heading"><b>친구들은 어디서 올까</b><small>도시 대표 지점 사이 직선거리</small></div><div class="commute-list">${commute.map((c,i)=>`<div>${face(survivalCast[c.id])}<span><b>${survivalCast[c.id].name}</b><small>${c.home} → ${r.name}</small></span><span class="commute-number"><b>${c.km}km</b><small>게임 추정 ${minutes(c.minutes)}</small></span></div>`).join('')}</div><p class="estimate-note">이동 시간·교통비는 거리 기반 게임 추정값입니다.<br>실제 교통편 시간표·요금·도로거리가 아닙니다.</p><button class="${destination===id?'venue-confirmed':'primary'}" id="confirm-venue">${destination===id?'✓ 이곳으로 모임 장소 선택됨':r.name+'에서 만나기'}</button><details class="regional-notes"><summary>지역 정보와 출처</summary><p>${r.detail}</p><a href="${r.source}" target="_blank" rel="noopener">관광 안내 자료 ↗</a><p>지역 명소는 자료를 참고했습니다. 게임의 대기·휴무·사고·말다툼은 창작입니다.</p></details>`;}
function preview(id,commit=false){previewDestination=id;if(commit)destination=id;const panel=document.getElementById('destination-panel');if(panel)panel.innerHTML=destinationPanel(id);const routes=document.getElementById('travel-routes');if(routes)routes.innerHTML=routesSVG(id);root.querySelectorAll('[data-pin],[data-candidate]').forEach(el=>{const same=(el.dataset.pin||el.dataset.candidate)===destination;el.classList.toggle('picked',same);el.setAttribute('aria-pressed',String(same));});const confirm=document.getElementById('confirm-venue');if(confirm)confirm.onclick=()=>preview(id,true);const start=document.getElementById('start');if(start){start.disabled=selected.length!==3||!destination;start.textContent=destination?Travel.region(destination).name+' 모임 시작 →':'지도에서 모임 장소를 골라주세요';}}
function lobby(){resumable=SurvivalEngine.restore(readGame('tw-game-save',null));state=null;const candidates=Travel.candidates(mapSeed);if(!candidates.some(r=>r.id===destination))destination=null;if(!candidates.some(r=>r.id===previewDestination))previewDestination=destination||candidates[0].id;
 root.innerHTML=`<section class="trip-intro"><p class="eyebrow">개테천 모임 대작전 · 전국 원정 편</p><h1>어디서 볼 건데?<span>지도 한 번 찍었다가, 단톡방이 터졌다.</span></h1><div class="intro-meta"><span>10개 도시 중 오늘의 후보 5곳</span><span>친구 3명 + 총무 1명</span><span>7라운드 · 지역별 사건</span></div></section><section class="party-picker"><details ${selected.length!==3?'open':''}><summary><b>오늘의 멤버</b><span>${selected.map(id=>`${face(survivalCast[id])}<strong>${survivalCast[id].nick}</strong><small>${survivalCities[survivalHomes[id]].name}</small>`).join('')}<em>멤버 변경 ${selected.length}/3</em></span></summary><p class="muted">최대 3명. 거주지와 선택에 따라 모임의 분위기가 달라집니다.</p><div class="cast">${survivalCast.map(p=>`<button class="cast-card ${selected.includes(p.id)?'selected':''}" data-person="${p.id}" aria-pressed="${selected.includes(p.id)}">${face(p)}<strong>${p.name}</strong><small>${survivalCities[survivalHomes[p.id]].name} 출발</small><span class="sample">${p.sample.slice(0,2).map(speak).join('<br>')}</span></button>`).join('')}</div></details><p id="party-status" role="status"></p></section><div class="map-section-heading"><div><h2>오늘 열린 모임 지도</h2><p>핀에 마우스를 올리면 미리 보기 · 클릭해서 선택</p></div><button id="shuffle">↻ 다른 후보 5곳</button></div><section class="destination-layout"><div class="map-pane"><div class="map-candidates" role="group" aria-label="오늘 모임 후보">${candidates.map(r=>`<button data-candidate="${r.id}" class="${destination===r.id?'picked':''}" aria-pressed="${destination===r.id}">${r.name}</button>`).join('')}</div>${mapSVG(candidates)}<div class="map-key"><span>● 오늘의 후보</span><span>◌ 친구의 출발지</span><span>↗ 친구별 이동선</span></div></div><aside class="destination-panel" id="destination-panel">${destinationPanel(previewDestination)}</aside></section><div class="trip-launch"><div><strong>공동 예산 12만 원</strong><p>넘긴 금액은 총무 개인 결제로 남습니다. 선택의 결과는 고른 뒤에 드러납니다.</p></div><button class="primary" id="start" ${selected.length!==3||!destination?'disabled':''}>${destination?Travel.region(destination).name+' 모임 시작 →':'지도에서 모임 장소를 골라주세요'}</button>${resumable?'<button id="resume">지난 모임 이어하기</button>':''}</div><div class="lobby-footer"><span>수집한 엔딩 ${collection.length} / ${Object.keys(survivalEndingBook).length}</span><span>LLM으로 미리 작성한 창작 대사 · 실시간 생성 없음</span></div><details class="ending-library"><summary>엔딩 도감</summary><div class="ending-book">${Object.entries(survivalEndingBook).map(([id,e])=>`<span class="${collection.includes(id)?'unlocked':''}">${collection.includes(id)?e[2]+' '+e[0]:'🔒 아직 만나지 못한 결말'}</span>`).join('')}</div></details><p class="map-credit">지도: <a href="https://www.naturalearthdata.com/" target="_blank" rel="noopener">Natural Earth</a> · 좌표: <a href="https://www.geonames.org/" target="_blank" rel="noopener">GeoNames</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a> · 거주지: 사용자 제공 · 정확한 주소는 사용하지 않음</p>`;
 root.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{const id=Number(b.dataset.person);if(selected.includes(id))selected=selected.filter(x=>x!==id);else if(selected.length<3)selected.push(id);else{document.getElementById('party-status').textContent='3명까지 고를 수 있어요. 한 명을 먼저 해제해주세요.';return;}lobby();const details=root.querySelector('.party-picker details');if(details)details.open=true;});
 root.querySelectorAll('[data-pin],[data-candidate]').forEach(el=>{const id=el.dataset.pin||el.dataset.candidate;el.onclick=()=>{preview(id,true);if(window.matchMedia&&window.matchMedia('(max-width:600px)').matches)document.getElementById('destination-panel').scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});};el.onmouseenter=()=>preview(id);el.onfocus=()=>preview(id);el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();preview(id,true)}};});
 document.getElementById('confirm-venue').onclick=()=>preview(previewDestination,true);document.getElementById('shuffle').onclick=()=>{mapSeed=newSeed();destination=null;previewDestination=null;lobby()};
 document.getElementById('start').onclick=()=>{if(selected.length!==3||!destination)return;state=SurvivalEngine.create(selected,mapSeed,destination);persist();render();window.scrollTo(0,0)};
 const resume=document.getElementById('resume');if(resume)resume.onclick=()=>{state=resumable;selected=[...state.party];destination=state.destination;render();window.scrollTo(0,0)};
}
function stats(){return `<div class="stats"><div class="cash"><span>네 사람의 공동 예산</span><strong>${money(state.budget)}</strong>${state.debt?`<small class="debt">총무 개인 결제 ${money(state.debt)}</small>`:''}</div>${[['energy','체력','♥'],['fullness','배부름','🍚'],['mood','분위기','✦']].map(([k,n,i])=>`<div class="meter ${state[k]<25?'danger':''}"><span>${i} ${n}<b>${state[k]}</b></span><progress max="100" value="${state[k]}" aria-label="${n}"></progress></div>`).join('')}</div>`;}
function members(){return `<div class="member-states">${state.party.map(id=>`<span>${face(survivalCast[id])}<b>${survivalCast[id].nick}</b><small>${state.personal[id]<25?'읽고 답이 없다':state.personal[id]<40?'입력하다 멈춤':state.personal[id]>80?'메시지가 늘었다':'대화에 참여 중'}</small></span>`).join('')}<div class="tension ${state.tension>=55?'hot':''}">갈등 ${state.tension}<progress max="100" value="${state.tension}" aria-label="갈등"></progress></div></div>`;}
const transcript=(end=false)=>SurvivalEngine.dialogue(state,end).map(t=>bubbles(survivalCast[t.id],t.lines)).join('');
function recap(){return `<details><summary>오늘의 선택과 사건 기록 (${state.actions.length})</summary><ol>${state.history.map((h,index)=>{const sc=SurvivalEngine.scene(state,index),incident=state.incidents.find(i=>i.step===index+1);return `<li><small>${sc.time} · ${sc.location}</small><br>${escapeHTML(h.label)}${incident?`<aside>⚡ ${survivalDilemmas[incident.id].title}<br><small>↳ ${escapeHTML(incident.label)}</small></aside>`:''}</li>`}).join('')}</ol></details>`;}
function render(){if(!state)return lobby();const ended=SurvivalEngine.ending(state),region=Travel.region(state.destination);
 if(state.phase==='end'){if(!collection.includes(ended[0])){collection.push(ended[0]);saveGame('tw-game-endings',collection);}const farthest=[...state.commute].sort((a,b)=>b.km-a.km)[0];root.innerHTML=`<section class="ending ending-${ended[0]}"><p class="eyebrow">${region.name} 모임 종료 · ENDING ${collection.length} / ${Object.keys(survivalEndingBook).length}</p><div class="end-icon">${ended[3]}</div><h1>${ended[1]}</h1><p class="epilogue">${ended[2]}</p><div class="ending-causes"><span>${region.emoji} ${region.name} · ${state.step}라운드</span><span>${survivalCast[farthest.id].name}의 원정 · ${farthest.home}에서 직선 ${farthest.km}km</span>${state.incidents.map(i=>`<span>${survivalDilemmas[i.id].icon} ${escapeHTML(i.label)}</span>`).join('')}</div>${stats()}${members()}<section class="chat final-chat"><div class="chat-head"><b>해산 뒤 단톡방</b><span>창작 후일담</span></div>${transcript(true)}</section>${recap()}<div class="launch"><button class="primary" id="again">같은 장소, 다른 하루</button><button id="party">지도에서 다시 정하기</button><button id="share">결과 복사</button></div><p id="copy-status" role="status"></p></section>`;document.getElementById('again').onclick=()=>{state=SurvivalEngine.create(state.party,newSeed(),state.destination);persist();render();window.scrollTo(0,0)};document.getElementById('party').onclick=lobby;document.getElementById('share').onclick=async()=>{const text=`개테천 모임 대작전 · ${region.name}: ${ended[1]}\n${state.party.map(id=>survivalCast[id].name).join(' · ')}\n${state.step}라운드 / 남은 예산 ${money(state.budget)}\nhttps://inzae1.github.io/theme-wiki/game.html`;try{await navigator.clipboard.writeText(text);document.getElementById('copy-status').textContent='결과를 복사했습니다.'}catch{document.getElementById('copy-status').textContent=text}};return;}
 const dilemma=state.phase==='dilemma',crisisReaction=state.phase==='dilemmaReaction',reaction=state.phase==='reaction'||crisisReaction,sc=SurvivalEngine.scene(state,Math.min(6,state.phase==='reaction'?state.step-1:state.step)),incident=dilemma||crisisReaction?SurvivalEngine.incident(state):null,last=crisisReaction?state.incidents.at(-1):state.history.at(-1),choice=crisisReaction?incident.choices.find(c=>c.id===last.choice):state.phase==='reaction'?SurvivalEngine.scene(state,state.step-1).choices.find(c=>c.id===last.choice):null;
 root.innerHTML=`<div class="play-top"><span>${region.emoji} ${region.name} · ${incident?'돌발 사건':`ROUND ${state.phase==='reaction'?state.step:state.step+1} / 7`}</span><small>일정 지연 ${state.delay}분</small><button id="back">지도·멤버</button></div><div class="steps" aria-hidden="true">${survivalScenes.map((s,i)=>`<span class="${i<state.step?'done':i===state.step?'current':''}"></span>`).join('')}</div>${stats()}${members()}<div class="play-grid"><section class="scene ${incident?'crisis':''}"><p class="eyebrow">${incident?incident.location:gameClock(sc.time)+' · '+sc.location}</p><h1>${incident?.title||sc.title}</h1><p>${incident?.intro||sc.intro}</p><div class="scene-art" aria-hidden="true">${incident?.icon||region.emoji}<span>${incident?'계획에 없던 갈림길':region.district}</span></div>${reaction?`<div class="chosen"><small>총무의 선택</small><strong>${choice.label}</strong><p>실제 지출 ${money(choice.cost||0)}${state.debt?' · 공동 예산 초과액은 개인 결제로 기록':''}</p>${crisisReaction?`<p class="outcome">${choice.text}</p>${choice.flag==='rematch'?`<p class="match-result">${state.flags.includes('won')?'역전승! 결과 화면이 저장됐다.':'또 졌다. 설욕은 다음 모임으로.'}</p>`:''}`:''}</div><button class="primary next" id="next">${ended?'오늘의 결말 보기':state.pending?'그런데, 잠깐…':'이후 상황 보기 →'}</button>`:`<div class="choices">${(incident||sc).choices.map(ch=>`<button data-choice="${ch.id}"><strong>${ch.label}</strong></button>`).join('')}</div>`}</section><section class="chat"><div class="chat-head"><b>개테천 · ${region.name} 모임</b><span>4명</span></div><p class="chat-date">${state.step===0?'아직 아무도 출발하지 않았다':incident?'평소와 달라진 대화':reaction?'선택 뒤의 대화':'지금 상황에 대한 이야기'}</p>${transcript()}<div class="chat-note">인물의 말투를 참고한 창작 대화</div></section></div>${recap()}`;
 document.getElementById('back').onclick=lobby;if(reaction)document.getElementById('next').onclick=()=>{state=SurvivalEngine.next(state);persist();render();window.scrollTo(0,0)};else root.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{state=dilemma?SurvivalEngine.resolve(state,b.dataset.choice):SurvivalEngine.choose(state,b.dataset.choice);persist();render();document.querySelector('.chat').scrollIntoView({block:'nearest',behavior:'smooth'})});
}
function gameClock(time){const [h,m]=time.split(':').map(Number),total=h*60+m+state.delay;return String(Math.floor(total/60)%24).padStart(2,'0')+':'+String(total%60).padStart(2,'0');}
document.getElementById('soft').onchange=e=>{soft=e.target.checked;saveGame('tw-game-soft',soft);render()};lobby();
